import java.util.*;
public class GenericsExamples { static class Pair<K,V>{K k;V v;Pair(K k,V v){this.k=k;this.v=v;}public K getKey(){return k;}public V getValue(){return v;}} static class Box<T>{T item;void addItem(T i){item=i;}T getItem(){return item;}} static <T> void swap(T[] a,int i,int j){T x=a[i];a[i]=a[j];a[j]=x;} public static void main(String[] x){Pair<String,Integer> p=new Pair<>("age",20);System.out.println(p.getKey()+"="+p.getValue());Box<String>b=new Box<>();b.addItem("Java");System.out.println(b.getItem());Integer[] a={1,2};swap(a,0,1);System.out.println(Arrays.toString(a));}}
